"""Relocation preserves source CLI callers and the existing generated bytes."""

import hashlib
from pathlib import Path
from unittest import mock

from astrid.core.element.registry import ElementRegistry
from astrid.core.foundation.paths import REPO_ROOT, load_checkout_script
from astrid.core.rendering import _effect_registry as generator


def test_packaged_generator_is_product_owned_and_in_existing_source_closure():
    from astrid.core.source_identity import source_checkout_closure

    assert Path(generator.__file__) == REPO_ROOT / 'astrid/core/rendering/_effect_registry.py'
    assert generator.TOOLS_DIR == REPO_ROOT
    closure = source_checkout_closure(REPO_ROOT)
    assert next(row for row in closure['components'] if row['component'] == 'core')['path'] == 'astrid/core'
    assert not any('scripts' in row['path'] for row in closure['components'])


def test_compatibility_cli_keeps_patchable_helpers_and_baseline_generated_bytes(monkeypatch):
    cli = load_checkout_script('gen_effect_registry')
    assert cli.generate_element_registry is generator.generate_element_registry
    assert cli.compute_generated_registry_state is generator.compute_generated_registry_state
    assert cli.TOOLS_DIR == generator.TOOLS_DIR
    monkeypatch.setattr(generator, '_element_registry', lambda: ElementRegistry(()))
    monkeypatch.setattr(generator, '_public_registry_ids', lambda: {
        kind: frozenset() for kind in generator.OUTPUTS})
    # Captured from the original implementation at f120c938, with the same
    # empty registry fixture. The public API probe is replaced, not executed.
    expected = {
        'effects': '4611570133ad55d1b8a1a029d605be639337a6e58c59f938644fd3ee274e47c7',
        'animations': '928d984096156f3f17fd0b0f1744927ff55f846c4ed1eff1e796411670bbbce6',
        'transitions': 'e7e6e007ae901ecdcac58ae56932ef1acdb8523e0d827f5572b442ac20a55b80',
    }
    state = cli.compute_generated_registry_state()
    assert state['content_hashes'] == expected
    for kind, digest in expected.items():
        raw = cli.generate_element_registry(kind).encode()
        assert hashlib.sha256(raw).hexdigest() == digest
    original = generator._write_generated_registry
    with mock.patch.object(cli, '_write_generated_registry', return_value=False):
        assert cli._main_unlocked([]) == 1
    assert generator._write_generated_registry is original
